import { chromium } from 'playwright';
const b = await chromium.launch();
const p = await b.newPage();
await p.setContent(`<!doctype html><html lang="ar" dir="rtl"><head><style>.ltr-run{direction:ltr;unicode-bidi:isolate}body{font:20px sans-serif}div{margin:6px;border:1px solid #ccc}</style></head><body>
<div id="plain">اختر 5–10 دقائق، ثم اضغط تم.</div>
<div id="split">اختر <bdi class="ltr-run">5</bdi>–<bdi class="ltr-run">10</bdi> دقائق، ثم اضغط تم.</div>
<div id="whole">اختر <bdi class="ltr-run">5–10</bdi> دقائق، ثم اضغط تم.</div>
<div id="plain2">هدف البروتين: 131–180 غ/يوم</div>
</body></html>`);
for (const id of ['plain','split','whole','plain2']){
  const r = await p.evaluate((i)=>{
    const el=document.getElementById(i);
    // measure x of each numeral by wrapping ranges over character offsets
    const out=[];
    const walk=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);
    let n;
    while((n=walk.nextNode())){
      const s=n.textContent;
      for(let k=0;k<s.length;k++){
        if(!/[0-9–-]/.test(s[k])) continue;
        const r2=document.createRange(); r2.setStart(n,k); r2.setEnd(n,k+1);
        const bb=r2.getBoundingClientRect();
        out.push({ch:s[k], x:Math.round(bb.x*10)/10});
      }
    }
    return out.sort((a,c)=>a.x-c.x).map(o=>o.ch).join('');
  }, id);
  console.log(id.padEnd(8), 'visual numerals left→right:', r);
}
await b.close();
